package com.myjavaworld.jftp;

import com.apple.eawt.ApplicationAdapter;
import com.apple.eawt.ApplicationEvent;

public class OSXAdapterOld extends ApplicationAdapter {

	// pseudo-singleton model; no point in making multiple instances
	// of the EAWT application or our adapter
	private static OSXAdapterOld theAdapter;
	private static com.apple.eawt.Application theApplication;
	// reference to the app where the existing quit, about, prefs code is
	private JFTPApplication mainApp;

	private OSXAdapterOld(JFTPApplication inApp) {
		mainApp = inApp;
	}

	// implemented handler methods. These are basically hooks into existing
	// functionality from the main app, as if it came over from another
	// platform.
	@Override
	public void handleAbout(ApplicationEvent ae) {
		if (mainApp != null) {
			ae.setHandled(true);
			mainApp.showAboutDialog();
		} else {
			throw new IllegalStateException(
					"handleAbout: MyApp instance detached from listener");
		}
	}

	@Override
	public void handlePreferences(ApplicationEvent ae) {
		if (mainApp != null) {
			mainApp.showPreferencesDialog();
			ae.setHandled(true);
		} else {
			throw new IllegalStateException(
					"handlePreferences: MyApp instance detached from listener");
		}
	}

	@Override
	public void handleQuit(ApplicationEvent ae) {
		if (mainApp != null) {
			/*
			 * / You MUST setHandled(false) if you want to delay or cancel the
			 * quit. / This is important for cross-platform development -- have
			 * a universal quit / routine that chooses whether or not to quit,
			 * so the functionality is identical / on all platforms. This
			 * example simply cancels the AppleEvent-based quit and / defers to
			 * that universal method.
			 */
			ae.setHandled(false);
			mainApp.quit();
		} else {
			throw new IllegalStateException(
					"handleQuit: MyApp instance detached from listener");
		}
	}

	// The main entry-point for this functionality. This is the only method
	// that needs to be called at runtime, and it can easily be done using
	// reflection (see MyApp.java)
	public static void registerMacOSXApplication(JFTPApplication inApp) {
		if (theApplication == null) {
			theApplication = new com.apple.eawt.Application();
		}

		if (theAdapter == null) {
			theAdapter = new OSXAdapterOld(inApp);
		}
		theApplication.addApplicationListener(theAdapter);
	}

	// Another static entry point for EAWT functionality. Enables the
	// "Preferences..." menu item in the application menu.
	public static void enablePrefs(boolean enabled) {
		if (theApplication == null) {
			theApplication = new com.apple.eawt.Application();
		}
		theApplication.setEnabledPreferencesMenu(enabled);
	}
