 */
public class NewLocalDirectoryAction implements ActionListener {

	private JFTP jftp = null;
	private static NewLocalDirectoryAction instance = null;

	private NewLocalDirectoryAction(JFTP jftp) {
		this.jftp = jftp;
	}

