package com.myjavaworld.jftp.actions;

import java.awt.Desktop;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.File;

import com.myjavaworld.ftp.RemoteFile;
import com.myjavaworld.gui.GUIUtil;
import com.myjavaworld.gui.SwingWorker;
import com.myjavaworld.jftp.FTPSession;
import com.myjavaworld.jftp.JFTP;

/**
 * An Action Implementation for uploading a signle file with a different name.
 * 
 * @author Sai Pullabhotla, psai [at] jMethods [dot] com
 * @version 2.0
 * 
 */
public class OpenRemoteFileAction implements ActionListener {

	private JFTP jftp = null;
	private static OpenRemoteFileAction instance = null;

	private OpenRemoteFileAction(JFTP jftp) {
		this.jftp = jftp;
	}

	public static synchronized OpenRemoteFileAction getInstance(JFTP jftp) {
		if (instance == null) {
			if (instance == null) {
				instance = new OpenRemoteFileAction(jftp);
			}
		}
		return instance;
	}

	public void actionPerformed(ActionEvent evt) {
		final FTPSession session = jftp.getCurrentSession();
		if (session == null || !session.isConnected()) {
			return;
		}

		final RemoteFile selectedFile = session.getSelectedRemoteFile();
		if (selectedFile == null) {
			return;
		}
		if (selectedFile.isDirectory()) {
			session.setRemoteWorkingDirectory(selectedFile);
			return;
		}
		session.clearAbortFlag();
		session.setBusy(true);
		new SwingWorker() {

			private File tempFile = null;

			@Override
			public Object construct() {
				tempFile = session.downloadToTempFile(selectedFile, true);
				return null;
			}

			@Override
			public void finished() {
				session.setBusy(false);
				if (tempFile == null) {
					return;
				}
				try {
					if (Desktop.isDesktopSupported()) {
						Desktop.getDesktop().open(tempFile);
					}
				} catch (Throwable t) {
					GUIUtil.showError(jftp, t);
				}
			}
		}.start();
	}
}/*
