public class PrintLocalFileAction implements ActionListener {

	private JFTP jftp = null;
	private static PrintLocalFileAction instance = null;

	private PrintLocalFileAction(JFTP jftp) {
		this.jftp = jftp;
	}

	public static synchronized PrintLocalFileAction getInstance(JFTP jftp) {
		if (instance == null) {
			if (instance == null) {
				instance = new PrintLocalFileAction(jftp);
			}
		}
		return instance;
