	}

	public void mouseClicked(MouseEvent evt) {
		if (evt.getClickCount() >= 2) {
			if (evt.getSource() == serverCertificatesTable) {
				int row = serverCertificatesTable.rowAtPoint(evt.getPoint());
				if (row >= 0) {
