public class NewRemoteFileDlg extends MDialog implements ActionListener {

	private static ResourceBundle resources = ResourceLoader
			.getBundle("com.myjavaworld.jftp.NewRemoteFileDlg");
	private static final String HELP_ID = "remote.newFile";
	private MTextField tfFile = null;
	private MButton butCreate = null;
	private MButton butCancel = null;
	private MButton butHelp = null;
	// private String file = null;
	private boolean approved = false;

	public NewRemoteFileDlg(Frame frame) {
		super(frame, resources.getString("title.dialog"), true);
		getContentPane().setLayout(new GridBagLayout());
		JFTPHelp2.getInstance().enableHelpKey(getRootPane(), HELP_ID);
		initComponents();
		pack();
	}

	public String getFile() {
		if (approved) {
			return tfFile.getText();
		}
		return null;
	}

	public void actionPerformed(ActionEvent evt) {
		if (evt.getSource() == butCreate) {
			if (!validateInput()) {
				return;
			}
			approved = true;
			close();
		} else if (evt.getSource() == butCancel) {
			close();
		}
	}

	private void close() {
		setVisible(false);
	}

	@Override
	protected void escape() {
		butCancel.doClick();
	}

	private boolean validateInput() {
		String message = null;
		Component errorComponent = null;
		if (tfFile.getText().trim().length() == 0) {
			message = resources.getString("error.file.required");
			errorComponent = tfFile;
		}
		if (message != null) {
			GUIUtil.showError(this, message);
			if (errorComponent != null) {
				errorComponent.requestFocusInWindow();
			}
			return false;
		}
		return true;
	}

