	}

	public String getFileName() {
		if (approved) {
			return tfFileName.getText();
		}
		return null;
	}

	public void actionPerformed(ActionEvent evt) {
		if (evt.getSource() == butUpload) {
			if (!validateInput()) {
				return;
			}
			approved = true;
			setVisible(false);
		}
		if (evt.getSource() == butCancel) {
			setVisible(false);
		}
	}

	@Override
